package computer.parachute.app

// Hand-written (not generated by `tauri android init`). Download on Android (src-tauri/src/updates.rs `update_install`):
// Rust downloads the newer build into the app's cache (cache/update/), checked against the feed's sha256, and asks this
// plugin to install it. It asks once for the right to install apps (Install unknown apps), looks at the file first (it
// must be Parachute, newer than this build, and signed by the same maker; Android would refuse anything else, but
// without saying so in words), then hands it to Android's installer in a PackageInstaller session. Android asks the
// person; on Update it replaces the app (and closes it), and any refusal comes back here, said plainly. Only the
// shell's Rust side calls it: no JavaScript-facing permission.

import android.app.Activity
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.pm.PackageInfo
import android.content.pm.PackageInstaller
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Build
import android.provider.Settings
import androidx.activity.result.ActivityResult
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleOwner
import app.tauri.annotation.ActivityCallback
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.JSObject
import app.tauri.plugin.Plugin
import java.io.File
import java.security.MessageDigest

@InvokeArg
class InstallArgs {
  lateinit var path: String
}

@TauriPlugin
class UpdatePlugin(private val activity: Activity) : Plugin(activity) {
  companion object {
    /** The plugin of the running app, for InstallStatus (Android's answers arrive as broadcasts). */
    @Volatile var current: UpdatePlugin? = null

    /** Android's answer, in words: what happened and, where there is one, what to do. */
    fun refusal(status: Int, message: String?): String {
      val m = message ?: ""
      return when (status) {
        PackageInstaller.STATUS_FAILURE_ABORTED -> "Not installed: the install was cancelled. Tap Download to try again."
        PackageInstaller.STATUS_FAILURE_BLOCKED -> "Not installed: Android blocked it (Play Protect or a rule on this device)."
        PackageInstaller.STATUS_FAILURE_CONFLICT ->
          if (m.contains("signature", true) || m.contains("UPDATE_INCOMPATIBLE"))
            "Not installed: the file isn't signed by the same maker as this Parachute."
          else "Not installed: it conflicts with the Parachute on this device."
        PackageInstaller.STATUS_FAILURE_INCOMPATIBLE ->
          if (m.contains("DOWNGRADE", true)) "Not installed: the file is an older build than this one."
          else "Not installed: that build doesn't run on this device."
        PackageInstaller.STATUS_FAILURE_INVALID -> "Not installed: the file isn't a whole app (the download may be broken). Try again."
        PackageInstaller.STATUS_FAILURE_STORAGE -> "Not installed: there isn't room on this device. Free some space and try again."
        else -> "Not installed: Android couldn't install it${if (m.isNotBlank()) " ($m)" else ""}."
      }
    }
  }

  init { current = this }

  /** The Download waiting on Android, and its file. One at a time: a new one replaces it. */
  private var waiting: Invoke? = null
  private var apk: File? = null
  /** Android's question, held until the app is in front to show it. */
  private var question: Intent? = null
  /** The session of the try waiting: Android's answers about another (one a newer try abandoned) are not for it. */
  @Volatile private var session = -1

  /** Only a file Rust wrote: an .apk directly in cache/update/. */
  private fun updateFile(path: String): File? {
    val dir = File(activity.cacheDir, "update").canonicalFile
    val file = File(path).canonicalFile
    return file.takeIf { it.parentFile == dir && it.isFile && it.name.endsWith(".apk") }
  }

  private fun finish(error: String?) {
    val invoke = waiting ?: return
    waiting = null
    apk = null
    question = null
    session = -1
    if (error == null) invoke.resolve(JSObject()) else invoke.reject(error)
  }

  @Command
  fun install(invoke: Invoke) {
    activity.runOnUiThread {
      val args = try { invoke.parseArgs(InstallArgs::class.java) } catch (e: Exception) {
        invoke.reject("bad install request"); return@runOnUiThread
      }
      val file = updateFile(args.path)
      if (file == null) { invoke.reject("The downloaded update is missing. Try again."); return@runOnUiThread }
      // a try still waiting on Android (its question went away without an answer): this one replaces it
      finish("Not installed: a newer try replaced this one.")
      waiting = invoke
      apk = file
      if (activity.packageManager.canRequestPackageInstalls()) {
        go()
      } else {
        // once: Android's own switch for Parachute (Install unknown apps), then back here
        try {
          startActivityForResult(invoke, Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES, Uri.parse("package:${activity.packageName}")), "allowed")
        } catch (e: Exception) {
          finish("Not installed: Parachute isn't allowed to install apps. Allow it in Android's Settings → Apps → Special app access → Install unknown apps.")
        }
      }
    }
  }

  @ActivityCallback
  private fun allowed(invoke: Invoke, result: ActivityResult) {
    if (waiting !== invoke) return
    if (activity.packageManager.canRequestPackageInstalls()) go()
    else finish("Not installed: Parachute needs your OK to install its updates. Tap Download and turn on “Allow from this source”.")
  }

  /** Looks at the file, then hands it to Android's installer. Off the main thread: the file is tens of MB. */
  private fun go() {
    val file = apk ?: return finish("The downloaded update is missing. Try again.")
    Thread {
      val error = try { looked(file) ?: commit(file) } catch (e: Exception) {
        "Not installed: Android couldn't take the file (${e.message ?: e.javaClass.simpleName})."
      }
      if (error != null) activity.runOnUiThread { finish(error) }
    }.start()
  }

  /** What's wrong with the file, before Android is asked (null: nothing found). */
  private fun looked(file: File): String? {
    val pm = activity.packageManager
    @Suppress("DEPRECATION")
    val flags = if (Build.VERSION.SDK_INT >= 28) PackageManager.GET_SIGNING_CERTIFICATES else PackageManager.GET_SIGNATURES
    @Suppress("DEPRECATION")
    val theirs = pm.getPackageArchiveInfo(file.path, flags)
      ?: return "Not installed: the downloaded file isn't an Android app. Try again."
    if (theirs.packageName != activity.packageName) return "Not installed: the downloaded file is another app, not Parachute."
    @Suppress("DEPRECATION")
    val ours = pm.getPackageInfo(activity.packageName, flags)
    val have = code(ours)
    val got = code(theirs)
    if (got < have) return "Not installed: the file is an older build than this one."
    if (got == have) return "Not installed: the file is the build you already have."
    // the signer: the file's must be this app's, or carry it in its key's history (a rotated key)
    val mine = signers(ours, false)
    val its = signers(theirs, true)
    if (mine != null && its != null && mine.intersect(its).isEmpty())
      return "Not installed: the file isn't signed by the same maker as this Parachute."
    return null
  }

  @Suppress("DEPRECATION")
  private fun code(info: PackageInfo): Long = if (Build.VERSION.SDK_INT >= 28) info.longVersionCode else info.versionCode.toLong()

  /** The signing certificates' SHA-256 (with `history`, the earlier keys of a rotated one too); null: unknown. */
  private fun signers(info: PackageInfo, history: Boolean): Set<String>? {
    val sigs = if (Build.VERSION.SDK_INT >= 28) {
      val s = info.signingInfo ?: return null
      if (history && !s.hasMultipleSigners()) s.signingCertificateHistory else s.apkContentsSigners
    } else {
      @Suppress("DEPRECATION") info.signatures
    } ?: return null
    if (sigs.isEmpty()) return null
    val sha = MessageDigest.getInstance("SHA-256")
    return sigs.map { sha.digest(it.toByteArray()).joinToString("") { b -> "%02x".format(b) } }.toSet()
  }

  /** A PackageInstaller session with the file, committed; Android's answers come to InstallStatus. */
  private fun commit(file: File): String? {
    val installer = activity.packageManager.packageInstaller
    // a session an earlier try left (the app was closed mid-install)
    for (old in installer.mySessions) runCatching { installer.abandonSession(old.sessionId) }
    val params = PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL).apply {
      setAppPackageName(activity.packageName)
      setSize(file.length())
      setInstallReason(PackageManager.INSTALL_REASON_USER)
    }
    val id = installer.createSession(params)
    session = id
    val session = installer.openSession(id)
    try {
      session.openWrite("parachute.apk", 0, file.length()).use { out ->
        file.inputStream().use { it.copyTo(out, 1 shl 16) }
        session.fsync(out)
      }
      val flags = PendingIntent.FLAG_UPDATE_CURRENT or (if (Build.VERSION.SDK_INT >= 31) PendingIntent.FLAG_MUTABLE else 0)
      val status = PendingIntent.getBroadcast(activity, id, Intent(activity, InstallStatus::class.java).setPackage(activity.packageName), flags)
      session.commit(status.intentSender)
      session.close()
      return null
    } catch (e: Exception) {
      runCatching { session.abandon() }
      throw e
    }
  }

  private fun resumed(): Boolean =
    (activity as? LifecycleOwner)?.lifecycle?.currentState?.isAtLeast(Lifecycle.State.RESUMED) ?: true

  /** Android's question ("Do you want to update this app?"): shown now if the app is in front, else when it is. */
  fun ask(id: Int, intent: Intent) {
    activity.runOnUiThread {
      if (waiting == null || id != session) return@runOnUiThread
      if (resumed()) show(intent) else question = intent
    }
  }

  private fun show(intent: Intent) {
    question = null
    try { activity.startActivity(intent) } catch (e: Exception) { finish("Not installed: Android's installer didn't open. Try again.") }
  }

  override fun onResume() {
    question?.let { show(it) }
  }

  /** Android's last word. On success the app is usually closed before it arrives. */
  fun done(id: Int, status: Int, message: String?) {
    activity.runOnUiThread {
      if (id == session) finish(if (status == PackageInstaller.STATUS_SUCCESS) null else refusal(status, message))
    }
  }
}

/** Where Android's installer answers (the session's status, UpdatePlugin.commit). Not exported: only the system's
 *  PendingIntent, made by this app, reaches it. */
class InstallStatus : BroadcastReceiver() {
  override fun onReceive(context: Context, intent: Intent) {
    val status = intent.getIntExtra(PackageInstaller.EXTRA_STATUS, PackageInstaller.STATUS_FAILURE)
    val plugin = UpdatePlugin.current ?: return
    val id = intent.getIntExtra(PackageInstaller.EXTRA_SESSION_ID, -1)
    if (status == PackageInstaller.STATUS_PENDING_USER_ACTION) {
      val question: Intent? = if (Build.VERSION.SDK_INT >= 33) intent.getParcelableExtra(Intent.EXTRA_INTENT, Intent::class.java)
        else @Suppress("DEPRECATION") intent.getParcelableExtra(Intent.EXTRA_INTENT)
      if (question != null) plugin.ask(id, question) else plugin.done(id, PackageInstaller.STATUS_FAILURE, "no question to ask")
      return
    }
    plugin.done(id, status, intent.getStringExtra(PackageInstaller.EXTRA_STATUS_MESSAGE))
  }
}
